// File excluded from build by automated review.// Reason: duplicate void putHeight(FSSpec&, int); main.cpp uses OSErr putHeight in putElevation.cpp#if 0#include "mesh.h"#include "FileStuff.h"#define		kPutIt		1#define		kRaiseIt	2#define		kLowerIt	3#define		kSmoothIt	4#define		kZeroIt		5void putHeight ( FSSpec &theMeshFSSpec, int theFunction );long doDialog( short newDialog );long SwapEndian ( long );void putHeight ( FSSpec &theMeshFSSpec, int theFunction ){//----------------------------------vars--------------------------------------------------	short		theMeshFileRef, theMapFileRef;	Str255		theMapFileName = "\p:Graphics.in:elevation.bmp";	OSErr		theError;	FSSpec		theMapFSSpec;	const short rHeightInputDialog = 130;	long factor;	long 	bitOffset;	char meshFolder[48] = ":mesh.out:";	unsigned char *TheMap;	int i, x, y;	int thePrevX, thePrevY, theNextX, theNextY;	long meshSize, meshWidth, meshHeight;	meshHeader theMeshHeader;	gridData *theGrid, *theTempGrid;//----------------------------------------------------------------------------------------		if ( theFunction != kZeroIt && theFunction != kSmoothIt )		factor =  doDialog( rHeightInputDialog );	if ( factor == 0 )		return;	theError = FSpOpenDF ( &theMeshFSSpec, fsCurPerm, &theMeshFileRef );	if ( theError != noErr ){		ParamText( "\pCan't open mesh file.", "\p", "\p", "\p" );		StopAlert ( 400, nil );		ExitToShell();	}	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	meshWidth = theMeshHeader.meshWidth * 16;	meshHeight = theMeshHeader.meshHeight * 16;	meshSize =  meshWidth * meshHeight;	theGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));	FileRead(theGrid, theMeshHeader.meshLength, theMeshFileRef);	theError = FSMakeFSSpec (0, 0, theMapFileName, &theMapFSSpec);	theError = FSpOpenDF ( &theMapFSSpec, fsCurPerm, &theMapFileRef );	if ( theError != noErr ){		ParamText( "\pCan't open elevation.bmp.", "\p", "\p", "\p" );		StopAlert ( 400, nil );		ExitToShell();	}	TheMap = (unsigned char *) NewPtr ( meshSize );// Get the offset to the bits and palette length	FileSeek ( theMapFileRef, 10L );	FileRead (&bitOffset, 4L, theMapFileRef);	bitOffset = SwapEndian ( bitOffset );	FileSeek ( theMapFileRef, bitOffset );	FileRead(TheMap, meshSize, theMapFileRef);	FSClose ( theMapFileRef );		switch ( theFunction ){			case kPutIt:			for ( y = (meshHeight - 1) * meshWidth, i = 0; y >= 0; y -= meshWidth )				for ( x = meshWidth - 1; x >= 0; x--, i++ )					theGrid[i].height = TheMap[x + y] * factor;		break;		case kRaiseIt:			for ( y = (meshHeight - 1) * meshWidth, i = 0; y >= 0; y -= meshWidth )				for ( x = meshWidth - 1; x >= 0; x--, i++ )					theGrid[i].height += TheMap[x + y] * factor;		break;		case kLowerIt:			for ( y = (meshHeight - 1) * meshWidth, i = 0; y >= 0; y -= meshWidth )				for ( x = meshWidth - 1; x >= 0; x--, i++ )					theGrid[i].height -= TheMap[x + y] * factor;		break;		case kSmoothIt:			theTempGrid = (struct gridData *) NewPtr (meshSize * sizeof(gridData));			for ( y = meshWidth; y < ((meshHeight - 1) * meshWidth); y += meshWidth )				for ( x = 1; x < (meshWidth - 1); x++ ){					if ( TheMap[x + y] != 0 ){						thePrevX = (x - 1) + y;						theNextX = (x + 1) + y;						thePrevY = x + (y - meshWidth);						theNextY = x + (y + meshWidth);						theTempGrid[ x + y].height =	(	theGrid[thePrevX].height +															theGrid[theNextX].height +															theGrid[thePrevY].height +															theGrid[theNextY].height ) / 4;					}				}															// now copy it back			for ( y = meshWidth; y < ((meshHeight - 1) * meshWidth); y += meshWidth )				for ( x = 1; x < (meshWidth - 1); x++ )					if ( TheMap[x + y] != 0 )						theGrid[ x + y].height = theTempGrid[ x + y].height;		break;		case kZeroIt:			for ( y = (meshHeight - 1) * meshWidth, i = 0; y >= 0; y -= meshWidth )				for ( x = meshWidth - 1; x >= 0; x--, i++ )					if ( TheMap[x + y] != 0 )						theGrid[i].height = 0;		break;	}	FileSeek ( theMeshFileRef, 1088L );	FileWrite (theGrid, theMeshHeader.meshLength, theMeshFileRef);	DisposePtr ( (Ptr) TheMap );	DisposePtr ( (Ptr) theGrid );	FSClose ( theMeshFileRef );}#endif